package com.eljefe.interviews;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.media.MediaRecorder;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.Gravity;import android.widget.*;import java.io.*;import java.util.*;import java.text.SimpleDateFormat;
public class MainActivity extends Activity{
 int pink=0xffff1493,bg=0xff05050a,white=0xffffffff;LinearLayout list;MediaRecorder rec;File current;ArrayList<String> qs=new ArrayList<>();ArrayList<File> audios=new ArrayList<>();String mode="";
 public void onCreate(Bundle b){super.onCreate(b);qs.add("¿Cómo valoras la temporada?");qs.add("¿Qué objetivos tiene el equipo?");qs.add("¿Qué mensaje mandas a la afición?");home();}
 TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(white);t.setGravity(Gravity.CENTER);t.setPadding(8,10,8,10);return t;}
 GradientDrawable shape(){GradientDrawable d=new GradientDrawable();d.setColor(0xff151520);d.setCornerRadius(22);d.setStroke(3,pink);return d;}
 void init(String title){LinearLayout root=new LinearLayout(this);root.setPadding(12,12,12,12);root.setOrientation(1);root.setBackgroundColor(bg);ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);sc.addView(list);root.addView(sc);setContentView(root);TextView h=txt(title,24);h.setTextColor(pink);h.setTypeface(null,1);list.addView(h);}
 void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(white);b.setTextSize(15);b.setAllCaps(false);b.setBackground(shape());b.setOnClickListener(v->r.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);list.addView(b,p);}
 void msg(String s){new AlertDialog.Builder(this).setTitle("EL JEFE 5.0").setMessage(s).setPositiveButton("Aceptar",null).show();}
 void home(){init("👑 EL JEFE 5.0\nENTREVISTAS FÚTBOL");list.addView(txt("C.D. SANTA ANA DE CABAÑAS RARAS",14));btn("🎙 GRABAR ENTREVISTA EN VÍDEO",()->video());btn("🎧 INICIAR GRABACIÓN DE AUDIO",()->startAudio());btn("⏹ DETENER Y GUARDAR AUDIO",()->stopAudio());btn("✂ RECORTAR AUDIO",()->pick("trim"));btn("🔊 MEJORAR VOZ Y REDUCIR RUIDO",()->pick("noise"));btn("〰 SUAVIZAR LA VOZ",()->pick("smooth"));btn("📋 PREGUNTAS PREPARADAS",()->questions());btn("📁 ARCHIVO DE ENTREVISTAS",()->archive());btn("⚙ AJUSTES",()->settings());}
 void video(){try{Intent i=new Intent(MediaStore.ACTION_VIDEO_CAPTURE);i.putExtra(MediaStore.EXTRA_VIDEO_QUALITY,1);startActivityForResult(i,50);}catch(Exception e){msg("No se pudo abrir la cámara.");}}
 void startAudio(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},70);return;}try{File dir=getExternalFilesDir(Environment.DIRECTORY_MUSIC);if(!dir.exists())dir.mkdirs();current=new File(dir,"Entrevista_"+new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.getDefault()).format(new Date())+".m4a");rec=new MediaRecorder();rec.setAudioSource(MediaRecorder.AudioSource.MIC);rec.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);rec.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);rec.setOutputFile(current.getAbsolutePath());rec.prepare();rec.start();msg("Grabación iniciada. Pulsa detener cuando termines.");}catch(Exception e){msg("No se pudo iniciar la grabación.");}}
 void stopAudio(){if(rec==null){msg("No hay grabación en curso.");return;}try{rec.stop();rec.release();rec=null;msg("Audio guardado en el archivo.");}catch(Exception e){msg("No se pudo guardar; prueba a grabar durante más tiempo.");try{rec.release();}catch(Exception x){}rec=null;}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==70&&g.length>0&&g[0]==0)startAudio();}
 void pick(String m){mode=m;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("audio/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,60);}catch(Exception e){msg("No se pudo abrir el selector de audio.");}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c==RESULT_OK&&d!=null){if(r==50)msg("Vídeo grabado. Consulta la Galería de tu Samsung.");if(r==60&&d.getData()!=null){String s=mode.equals("trim")?"El recorte de audio todavía necesita integrarse.":"El procesamiento de suavizado de voz y reducción de ruido todavía necesita integrarse.";msg(s);try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(d.getData(),"audio/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){}}}}
 void archive(){init("📁 ARCHIVO DE ENTREVISTAS");File dir=getExternalFilesDir(Environment.DIRECTORY_MUSIC);File[] fs=dir==null?null:dir.listFiles();btn("🎙 INICIAR GRABACIÓN",()->startAudio());btn("⏹ DETENER GRABACIÓN",()->stopAudio());if(fs!=null)for(File f:fs)if(f.isFile()){btn("▶ "+f.getName(),()->{try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.fromFile(f),"audio/*");startActivity(i);}catch(Exception e){msg("No se pudo reproducir.");}});}btn("VOLVER",()->home());}
 void questions(){init("📋 PREGUNTAS PREPARADAS");for(String q:qs)list.addView(txt("• "+q,17));btn("＋ AÑADIR PREGUNTA",()->{EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("Nueva pregunta").setView(e).setPositiveButton("Guardar",(d,w)->{if(e.length()>0)qs.add(e.getText().toString());questions();}).setNegativeButton("Cancelar",null).show();});btn("VOLVER",()->home());}
 void settings(){init("⚙ AJUSTES");list.addView(txt("EL JEFE 5.0 · C.D. Santa Ana\nDiseño negro y fucsia",17));btn("VOLVER",()->home());}
}